[
  {
    "function": "manage_script",
    "args": {
      "action": "create",
      "name": "FPSPlayerController",
      "path": "Assets/Scripts/Controllers/",
      "namespace": "MyGame.Controllers",
      "script_type": "MonoBehaviour",
      "contents": "using UnityEngine;

namespace MyGame.Controllers
{
    public class FPSPlayerController : MonoBehaviour
    {
        [Header("Movement Settings")]
        public float moveSpeed = 5f;
        public float lookSensitivity = 2f;
        public Transform cameraTransform;

        [Header("Shooting Settings")]
        public GameObject projectilePrefab;
        public Transform shootOrigin;
        public float projectileSpeed = 20f;
        public float fireRate = 0.25f;

        private float nextFireTime = 0f;
        private CharacterController controller;
        private Vector2 lookRotation;

        void Awake()
        {
            controller = GetComponent<CharacterController>();
            if (cameraTransform == null)
                cameraTransform = Camera.main.transform;
        }

        void Update()
        {
            HandleMovement();
            HandleLook();
            HandleShooting();
        }

        void HandleMovement()
        {
            float h = Input.GetAxis("Horizontal");
            float v = Input.GetAxis("Vertical");
            Vector3 moveDir = new Vector3(h, 0, v).normalized;
            if (moveDir.magnitude > 0)
                moveDir = transform.TransformDirection(moveDir);

            controller.SimpleMove(moveDir * moveSpeed);
        }

        void HandleLook()
        {
            float mouseX = Input.GetAxis("Mouse X") * lookSensitivity;
            float mouseY = Input.GetAxis("Mouse Y") * lookSensitivity;

            lookRotation.x += mouseX;
            lookRotation.y -= mouseY;
            lookRotation.y = Mathf.Clamp(lookRotation.y, -90f, 90f);

            transform.rotation = Quaternion.Euler(0, lookRotation.x, 0);
            cameraTransform.localEulerAngles = new Vector3(lookRotation.y, 0, 0);
        }

        void HandleShooting()
        {
            if (Input.GetMouseButton(0) && Time.time >= nextFireTime)
            {
                Shoot();
                nextFireTime = Time.time + fireRate;
            }
        }

        void Shoot()
        {
            if (projectilePrefab == null || shootOrigin == null) return;

            GameObject proj = Instantiate(projectilePrefab, shootOrigin.position, shootOrigin.rotation);
            Rigidbody rb = proj.GetComponent<Rigidbody>();
            if (rb != null)
                rb.velocity = shootOrigin.forward * projectileSpeed;
        }
    }
}"
    }
  }
]
